public static <T extends Comparable<? super T>> int binarySearch(List<T> list, T key) {
    int low = 0, high = list.size() - 1;
    while (low <= high) {
        int mid = (low + high) >>> 1;
        int cmp = list.get(mid).compareTo(key);
        if (cmp < 0) low = mid + 1;
        else if (cmp > 0) high = mid - 1;
        else return mid;
    }
    return -(low + 1);
}
